import{_ as i,o as u,c as n,a2 as o}from"./chunks/framework.CqpfiAoK.js";const z=JSON.parse('{"title":"Miongozo ya Uchunguzi awali, Kisha Kuingilia Kazi kwa Mdogo","description":"","frontmatter":{},"headers":[],"relativePath":"sw/83-先观测后有限干涉准则.md","filePath":"sw/83-先观测后有限干涉准则.md"}'),e={name:"sw/83-先观测后有限干涉准则.md"};function t(k,a,h,w,m,g){return u(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="miongozo-ya-uchunguzi-awali-kisha-kuingilia-kazi-kwa-mdogo" tabindex="-1">Miongozo ya Uchunguzi awali, Kisha Kuingilia Kazi kwa Mdogo <a class="header-anchor" href="#miongozo-ya-uchunguzi-awali-kisha-kuingilia-kazi-kwa-mdogo" aria-label="Permalink to &quot;Miongozo ya Uchunguzi awali, Kisha Kuingilia Kazi kwa Mdogo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>83</td></tr><tr><td>Moduli</td><td>Mwingiliano wa Kati ya Ndege na Kanuni za Wakati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Uchunguzi awali, kuingilia kazi kwa mdogo, itifaki ya uchunguzi, kizingiti cha kuingilia kazi, tathmini ya sababu</td></tr></tbody></table><h2 id="_1-falsafa-ya-msingi-ya-miongozo" tabindex="-1">1. Falsafa ya Msingi ya Miongozo <a class="header-anchor" href="#_1-falsafa-ya-msingi-ya-miongozo" aria-label="Permalink to &quot;1. Falsafa ya Msingi ya Miongozo&quot;">​</a></h2><p>&quot;Uchunguzi awali, kisha kuingilia kazi kwa mdogo&quot; ni miongozo ya kwanza ya uendeshaji wa kurudi nyuma kwa wakati na kichunguzi cha kati ya ndege cha Hengyuanzhou, falsafa yake ya msingi inaweza kufupishwa katika heri kumi na sita: &quot;Angalia bila kugusa, pima bila kuingilia, uchunguzi kabla ya hatua, hatua kwa mdogo.&quot; Uanzishaji wa miongozo hii unategemea heshima ya kina kwa sheria za sababu za ulimwengu — kuingilia kazi moja kwa moja yoyote kwenye zamani au ndege nyingine inaweza kusababisha mmenuko wa sababu wa kutokitarajiwa, na uchunguzi wa kutosha wa awali ni njia pekee ya kuaminika ya kupunguza hatari kwa kiwango cha chini.</p><p>Msingi wa falsafa wa miongozo ni kanuni ya &quot;unyenyevu wa utambuzi&quot;. Hengyuanzhou inakubali kwamba hata mwenye nguvu wa juu zaidi wa ndege hawezi kubeba kabisa uhusiano wote wa sababu wa nodi moja ya wakati au ustaarabu wa ndege moja. Kwa hivyo, kabla ya kuchukua hatua yoyote ya kuingilia kazi, lazima ufanyike uchunguzi kamili kwa mtazamo wa uangalifu zaidi, na uelewe muundo wa sababu na mwelekeo wa mageuzi wa kipengele cha lengwa kadiri iwezekanavyo. Pekee chini ya msingi wa data za uchunguzi za kutosha na tathmini ya hatari iliyo wazi, ndipo kuingilia kazi kwa mdogo kunaruhusiwa.</p><p>&quot;Uchunguzi awali, kisha kuingilia kazi kwa mdogo&quot; sio hatua mbili za kujitegemea, bali ni mzunguko wa uendeshaji wa kibaolojia: uchunguzi hutoa msingi wa kuingilia kazi, na matokeo ya kuingilia kazi pia hutoa taarifa kama data mpya za uchunguzi, zote mbili zinazozunguka na kuendelea hatua kwa hatua. Mzunguko huu unahakikisha kuwa kila kuingilia kazi kunajengwa kwenye msingi wa utambuzi wa hivi karibuni na kamili zaidi.</p><h2 id="_2-kanuni-za-uendeshaji-za-hatua-ya-uchunguzi" tabindex="-1">2. Kanuni za Uendeshaji za Hatua ya Uchunguzi <a class="header-anchor" href="#_2-kanuni-za-uendeshaji-za-hatua-ya-uchunguzi" aria-label="Permalink to &quot;2. Kanuni za Uendeshaji za Hatua ya Uchunguzi&quot;">​</a></h2><p>Hatua ya uchunguzi ni msingi wa mchakato wote wa uendeshaji, ubora wake unaamua moja kwa moja usalama na ufanisi wa kuingilia kazi kinachofuata. Hatua ya uchunguzi lazima ifuate kanuni zifuatazo za uendeshaji:</p><h3 id="_2-1-mahitaji-ya-muda-wa-uchunguzi" tabindex="-1">2.1 Mahitaji ya Muda wa Uchunguzi <a class="header-anchor" href="#_2-1-mahitaji-ya-muda-wa-uchunguzi" aria-label="Permalink to &quot;2.1 Mahitaji ya Muda wa Uchunguzi&quot;">​</a></h3><p>Muda wa uchunguzi haupaswi kuwa chini ya 1% ya urefu kamili wa kipindi cha lengwa, na muda kamili haupaswi kuwa chini ya masaa 72 ya wakati wa kiwango cha ndege ya mwenyewe. Kwa mfano, kufanya uchunguzi wa kurudi nyuma kwenye kipindi cha kihistoria chenye urefu wa miaka 100, hatua ya uchunguzi safi haipaswi kuwa chini ya mwaka 1; kuchunguza kipindi chenye urefu wa miaka 10, hatua ya uchunguzi safi haipaswi kuwa chini ya masaa 72. Hitaji hili la muda wa chini linahakikisha kuwa mchunguzi anaweza kupata mabadiliko ya mara kwa mara na mwelekeo wa muda mrefu ndani ya kipindi cha lengwa, na kuepuka uamuzi wa upande mmoja kutokana na dirisha la uchunguzi lifupi mno.</p><h3 id="_2-2-mahitaji-ya-mwelekeo-wa-uchunguzi" tabindex="-1">2.2 Mahitaji ya Mwelekeo wa Uchunguzi <a class="header-anchor" href="#_2-2-mahitaji-ya-mwelekeo-wa-uchunguzi" aria-label="Permalink to &quot;2.2 Mahitaji ya Mwelekeo wa Uchunguzi&quot;">​</a></h3><p>Uchunguzi lazima ufunike mwelekeo matano yafuatayo, hakima yoyote haipaswi kukosa:</p><table tabindex="0"><thead><tr><th>Mwelekeo wa Uchunguzi</th><th>Maudhui ya Mahususi</th><th>Mbinu ya Uchunguzi</th></tr></thead><tbody><tr><td>Mwelekeo wa vifaa</td><td>Mazingira ya kijiografia, mfumo wa ikolojia, miundombinu, usambazaji wa rasilimali za vifaa</td><td>Skana ya nafasi, uchambuzi wa vifaa</td></tr><tr><td>Mwelekeo wa nishati</td><td>Usambazaji wa msongamano wa nishati, vigezo vya sheria, mifumo ya mtiririko wa nishati</td><td>Uchambuzi wa wigo wa nishati, ugunduzi wa sheria</td></tr><tr><td>Mwelekeo wa maisha</td><td>Usambazaji wa spishi, idadi ya idadi ya watu, hali ya afya, kiwango cha mageuzi</td><td>Skana ya dalili za maisha, sampuli za jeni</td></tr><tr><td>Mwelekeo wa fahari</td><td>Fomu ya ustaarabu, muundo wa kijamii, dhana za mawazo, mwelekeo wa fahari ya pamoja</td><td>Ufuatiliaji wa mwepesi wa eneo la fahari, uchambuzi wa kitamaduni</td></tr><tr><td>Mwelekeo wa sababu</td><td>Minyororo ya msingi ya sababu, nodi za kihistoria, mwelekeo wa mageuzi, hatari zinazowezekana</td><td>Ufuatiliaji wa mnyororo wa sababu, tathmini ya mwelekeo</td></tr></tbody></table><h3 id="_2-3-mahitaji-ya-ubagamizi-wa-uchunguzi" tabindex="-1">2.3 Mahitaji ya Ubagamizi wa Uchunguzi <a class="header-anchor" href="#_2-3-mahitaji-ya-ubagamizi-wa-uchunguzi" aria-label="Permalink to &quot;2.3 Mahitaji ya Ubagamizi wa Uchunguzi&quot;">​</a></h3><p>Hatua ya uchunguzi lazima idumishe ubagamizi kwa mkali, mchunguzi hawezi kuathiri kipengele cha uchunguzi kwa njia yoyote. Vitendo vilivyokataliwa mahususi vinajumuisha: kufanya mawasiliano ya aina yoyote na kipengele cha uchunguzi, kuacha alama yoyote ya vifaa au nishati katika eneo la uchunguzi, kuongoza au kupendekeza tabia ya kipengele cha uchunguzi, na kutoa mabadiliko yoyote ya hiari yanayoweza kuchunguzwa ndani ya eneo la fahari.</p><p>Hali ya uwepo wa mchunguzi wakati wa hatua ya uchunguzi inapaswa kuwa &quot;utambuzi wa mwepesi safi&quot;, yaani kupokea taarifa tu bila kutoa taarifa yoyote. Kifaa cha nanga ya nanga kitatengeneza &quot;eneo la kinga la uchunguzi&quot; kwa ajili ya mchunguzi, likihakikisha kuwa uwepo wa mchunguzi hautachunguzwa na kipengele cha uchunguzi, wakati huo huo kuzuia mchunguzi asitoe kwa bahati nakala za usumbufu.</p><h2 id="_3-ufafanuzi-na-kizingiti-cha-kuingilia-kazi-kwa-mdogo" tabindex="-1">3. Ufafanuzi na Kizingiti cha Kuingilia Kazi kwa Mdogo <a class="header-anchor" href="#_3-ufafanuzi-na-kizingiti-cha-kuingilia-kazi-kwa-mdogo" aria-label="Permalink to &quot;3. Ufafanuzi na Kizingiti cha Kuingilia Kazi kwa Mdogo&quot;">​</a></h2><p>Baada ya kukamilisha hatua ya uchunguzi, timu ya uendeshaji lazima iwasilishe &quot;Ripoti ya Uchunguzi na Tathmini ya Uwezo wa Kuingilia Kazi&quot;, na baada ya kupitishwa na Kamati ya Sheria za Wakati au Ofisi ya Usimamizi wa Ndege, ndipo inaweza kuingia katika hatua ya kuingilia kazi kwa mdogo. &quot;Mdogo&quot; katika &quot;kuingilia kazi kwa mdogo&quot; unaonyeshwa katika viwango vitatu vifuatavyo:</p><h3 id="_3-1-upeo-mdogo" tabindex="-1">3.1 Upeo Mdogo <a class="header-anchor" href="#_3-1-upeo-mdogo" aria-label="Permalink to &quot;3.1 Upeo Mdogo&quot;">​</a></h3><p>Hatua ya kuingilia kazi lazima iwe mdogo kwa mkali ndani ya &quot;eneo la ruhusa ya kuingilia kazi&quot; lililobainishwa katika hati ya uidhinishaji, eneo hili kwa kawaida halizidi 1% ya ukubwa kamili wa eneo la uchunguzi. Hatua yoyote ya kuingilia kazi nje ya eneo la ruhusa inachukuliwa kama uendeshaji wa makosa, muendeshaji atabeba maslahi ya kisheria.</p><h3 id="_3-2-kiwango-mdogo" tabindex="-1">3.2 Kiwango Mdogo <a class="header-anchor" href="#_3-2-kiwango-mdogo" aria-label="Permalink to &quot;3.2 Kiwango Mdogo&quot;">​</a></h3><p>Patisho la nishati na kiasi cha sindano ya taarifa cha kuingilia kazi halipaswi kuzidi &quot;kizingiti cha kuingilia kazi&quot;. Kizingiti cha kuingilia kazi kinatamkwa kwa nguvu kulingana na unyeti wa sababu wa kipengele cha lengwa, formula ya mahesabu ni: kizingiti cha kuingilia kazi = nishati kamili ya eneo la lengwa × kigezo cha unyeti wa sababu × 0.0001. Kigezo cha unyeti wa sababu kina thamani kutoka 0.1 hadi 10; kadiri kiwango cha ustaarabu kinavyozidi, kadiri nodi ya kihistoria inavyokuwa muhimu, ndivyo kigezo kinavyozidi. Hii inamaanisha kuwa kizingiti cha kuingilia kazi kwenye nodi za kihistoria za muhimu ni cha chini sana, karibu hakiruhusi sindano yoyote ya nishati ya kweli.</p><h3 id="_3-3-wakati-mdogo" tabindex="-1">3.3 Wakati Mdogo <a class="header-anchor" href="#_3-3-wakati-mdogo" aria-label="Permalink to &quot;3.3 Wakati Mdogo&quot;">​</a></h3><p>Muda wa kuendelea wa hatua ya kuingilia kazi haupaswi kuzidi 10% ya muda kamili wa hatua ya uchunguzi, na muda kamili haupaswi kuzidi masaa 24 ya wakati wa kiwango cha ndege ya mwenyewe. Baada ya kuingilia kazi kumalizika, muendeshaji lazima aondoke mara moja kwenye kipindi cha lengwa au ndege ya lengwa, asiweze kukaa.</p><h2 id="_4-tathmini-na-marekebisho-ya-sababu-baada-ya-kuingilia-kazi" tabindex="-1">4. Tathmini na Marekebisho ya Sababu baada ya Kuingilia Kazi <a class="header-anchor" href="#_4-tathmini-na-marekebisho-ya-sababu-baada-ya-kuingilia-kazi" aria-label="Permalink to &quot;4. Tathmini na Marekebisho ya Sababu baada ya Kuingilia Kazi&quot;">​</a></h2><p>Baada ya kuingilia kazi kwa mdogo kumalizika, timu ya uendeshaji lazima ifanye mara moja &quot;tathmini ya sababu baada ya kuingilia kazi&quot;, na kufuatilia mabadiliko ya mnyororo wa sababu yanayosababishwa na hatua ya kuingilia kazi kupitia mtandao wa nanga. Maudhui ya tathmini yanajumuisha: ukubwa wa upotofu wa sababu, upeo wa uenezi wa upotofu, mwelekeo wa mageuzi ya muda mrefu wa upotofu, na kama kuna hatari ya paradox.</p><p>Ikiwa tathmini inagundua kuwa upotofu wa sababu umezidi upeo wa kukubalika (ukubwa wa upotofu umezidi 0.01% ya kiasi kamili cha sababu cha eneo la lengwa), timu ya uendeshaji lazima ianze mara moja &quot;mchakato wa marekebisho ya sababu&quot;. Njia za marekebisho ya sababu zinajumuisha: sindano ya taarifa ya fidia kwenye nodi za wakati zinazofuata, marekebisho madogo ya mnyororo wa sababu kupitia mtandao wa nanga, na katika hali za kizungumzia kufanya kurudi nyuma mara ya pili ili kutoa athari ya kuingilia kazi awali.</p><p>Vitendo vyote vya kuingilia kazi na matokeo ya tathmini ya sababu yao lazima viandikishwe katika &quot;Hifadhi ya Kumbukumbu za Uendeshaji wa Wakati&quot;, vihifadhiwe kwa kudumu, na vitumike kwa ajili ya ukaguzi wa baadaye na utafiti.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Miongozo ya uchunguzi awali, kisha kuingilia kazi kwa mdogo ni tathmini ya hekima ya Hengyuanzhou katika uwanja wa uendeshaji wa wakati na ndege. Kwa uchunguzi wa kutosha kama msingi, kizingiti cha mkali kama mipaka, na tathmini ya baadaye kama dhamana, inajenga muundo wa uendeshaji wa &quot;kujua kabla ya hatua, hatua kwa mdogo&quot;. Lengo la msingi la miongozo hii sio kushika mikono na miguu ya uchunguzi, bali kuhakikisha kuwa kila uchunguzi haufanyike kwa gharama ya kuharibu mpangilio wa sababu wa ulimwengu.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>82-Kanuni za Msingi za Kurudi Nyuma kwa Wakati</li><li>84-Muhtasari wa Itifaki ya Kichunguzi</li><li>89-Mchakato wa Kuzuia na Kudhibiti Paradox ya Wakati</li></ul>',32)])])}const d=i(e,[["render",t]]);export{z as __pageData,d as default};
